sp_header_footer.client_script:
api.controller = function($window) {
    var c = this;
    c.openSparkleAI = function() {       
        var suffix = ($window.location.pathname || '/sp').split('/').filter(Boolean)[0] || 'sp';
        var target = $window.location.origin + '/' + suffix + '?id=incentiq_chat';
        $window.open(target, '_blank', 'noopener,noreferrer');
    };
};

sp_header_footer.css:
/* USER AVATAR */
.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #2563eb;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
}
.profile-card {
    padding: 12px;
    display: flex;
    align-items: center;
    gap: 14px;
    width: 100%;
    max-width: 560px;
    border: 1px solid rgba(255,255,255,0.08);
}
.profile-info h2{
    margin: 0;    
    font-size: 36px;
    font-weight: 100;
}
/* HEADER */
.sim-header {
  width: 100%;
  background: #fff;
  border-bottom: 1px solid #e5e7eb;
  position: sticky;
  top: 0;
  z-index: 100;
}
/* CONTAINER */
.sim-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  padding: 0 24px;
  flex-wrap: nowrap;
}
/* LEFT GROUP */
.sim-left {
  display: flex;
  align-items: center;
  gap: 20px;
  flex: 1;
  min-width: 0;
}
/* LOGO */
.sim-logo {
  display: flex;
  align-items: center;
}
.sim-logo-tooltip {
  position: relative;
}

.sim-logo-tooltip-text {
  position: absolute;
  top: 110%;
  left: 0;
  background: #10182B;
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
  padding: 6px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  transition: opacity 0.18s ease, transform 0.18s ease, visibility 0.18s ease;
  pointer-events: none;
  z-index: 200;
}

.sim-logo-tooltip-text::before {
  content: "";
  position: absolute;
  bottom: 100%;
  left: 14px;
  border: 5px solid transparent;
  border-bottom-color: #10182B;
}

.sim-logo-tooltip:hover .sim-logo-tooltip-text {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.logo-link {
  display: flex;
  align-items: center;
}
.logo-img {
  height: 34px;
  width: auto;
}
/* NAVIGATION */
.sim-nav {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}
.sim-nav a {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: #374151 !important;
  font-size: 13px;
  font-weight: 500;
  transition: all 0.2s ease;
}
/* HOVER EFFECT */
.sim-nav a:hover {
  background: #f3f4f6;
  color: #111827 !important;
}
/* ACTIVE MENU ITEM (DYNAMIC HIGHLIGHT) */
.sim-nav a.active {
  background: #e8f0ff !important;
  color: #2563eb !important;
  border-radius: 8px;
  font-weight: 600 !important;
  padding: 8px 14px;
}
/* RIGHT SIDE */
.sim-right {
  display: flex;
  align-items: center;
  gap: 12px;
  white-space: nowrap;
}
/* PERIOD BUTTON */
.period-btn {
  border: 1px solid #d1d5db;
  padding: 5px 10px;
  background: #fff;
  border-radius: 6px;
  font-size: 12px;
  cursor: pointer;
}
/* NAVBAR RIGHT FIX */
.navbar-right {
  display: flex !important;
  align-items: center;
  margin: 0 !important;
  padding: 0 !important;
  list-style: none;
}
.navbar-right > li {
  float: none !important;
  display: flex;
  align-items: center;
}
/* DROPDOWN */
.dropdown {
  position: relative;
}
.dropdown-menu {
  position: absolute;
  top: 110%;
  right: 0;
  z-index: 9999;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  min-width: 150px;
  box-shadow: 0 8px 20px rgba(0,0,0,0.08);
}
.dropdown-menu li a {
  padding: 10px 14px;
  display: block;
  color: #374151 !important;
  text-decoration: none;
}
.dropdown-menu li a:hover {
  background: #f9fafb;
}
/* FINAL FORCE */
.sim-header * {
  white-space: nowrap;
}
.sim-right {
    display: flex;
    align-items: center;
    gap: 12px;
}
.sparkle-btn {
    background: transparent;
    border: none;
    padding: 0;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}
.sparkle-btn:hover {
    transform: scale(1.1);
}
.sparkle-icon {
    width: 32px;
    height: 32px;
    object-fit: contain;
    display: block;
    animation: sim-sparkle-spin 6s linear infinite;
}

@keyframes sim-sparkle-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .sparkle-icon {
    animation: none;
  }
}
.sparkle-tooltip-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.sparkle-tooltip-text {
  position: absolute;
  top: 110%;
  right: 0;
  background: #10182B;
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
  padding: 6px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  transition: opacity 0.18s ease, transform 0.18s ease, visibility 0.18s ease;
  pointer-events: none;
  z-index: 200;
}

.sparkle-tooltip-text::before {
  content: "";
  position: absolute;
  bottom: 100%;
  right: 14px;
  border: 5px solid transparent;
  border-bottom-color: #10182B;
}

.sparkle-tooltip-wrap:hover .sparkle-tooltip-text {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.navbar-right {
    margin-bottom: 0 !important;
}
.approval-badge {
    float: right;
    min-width: 18px;
    height: 18px;
    padding: 0 6px;
    background: #dc3545;
    color: #fff;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 600;
    line-height: 18px;
    text-align: center;
}

/* =========================================================
   MOBILE RESPONSIVE
   ========================================================= */

@media (max-width: 767px) {

  /* -------------------------
     HEADER
     ------------------------- */

  .sim-header {
    position: sticky;
    top: 0;
    width: 100%;
    overflow: visible;
  }

  .sim-container {
    height: auto;
    min-height: 58px;
    padding: 10px 14px;
    gap: 10px;
    flex-wrap: nowrap;
  }

  .sim-left {
    gap: 10px;
    min-width: 0;
    flex: 1 1 auto;
  }

  /* -------------------------
     LOGO
     ------------------------- */

  .logo-img {
    height: 30px;
    max-width: 120px;
  }

  .sim-logo {
    flex-shrink: 0;
  }

  /* -------------------------
     NAVIGATION
     ------------------------- */

  .sim-nav {
    gap: 4px;
    overflow-x: auto;
    overflow-y: hidden;
    max-width: 100%;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
  }

  .sim-nav::-webkit-scrollbar {
    display: none;
  }

  .sim-nav a {
    padding: 7px 9px;
    font-size: 12px;
    gap: 4px;
    flex-shrink: 0;
  }

  .sim-nav a.active {
    padding: 7px 9px;
  }

  /* -------------------------
     RIGHT SIDE
     ------------------------- */

  .sim-right {
    gap: 7px;
    flex-shrink: 0;
  }

  .period-btn {
    padding: 5px 7px;
    font-size: 11px;
  }

  .sparkle-icon {
    width: 28px;
    height: 28px;
  }

  /* -------------------------
     NAVBAR RIGHT
     ------------------------- */

  .navbar-right {
    gap: 6px;
    flex-shrink: 0;
  }

  .navbar-right > li {
    flex-shrink: 0;
  }

  /* -------------------------
     PROFILE
     ------------------------- */

  .profile-card {
    padding: 10px;
    gap: 10px;
    max-width: 100%;
  }

  .profile-info h2 {
    font-size: 24px;
    line-height: 1.2;
  }

  .avatar {
    width: 30px;
    height: 30px;
    font-size: 11px;
    flex-shrink: 0;
  }

  /* -------------------------
     DROPDOWN
     ------------------------- */

  .dropdown-menu {
    position: absolute;
    right: 0;
    top: 110%;
    min-width: 145px;
    max-width: calc(100vw - 20px);
  }

  .dropdown-menu li a {
    padding: 10px 12px;
    font-size: 13px;
  }

  /* -------------------------
     APPROVAL BADGE
     ------------------------- */

  .approval-badge {
    min-width: 17px;
    height: 17px;
    padding: 0 5px;
    font-size: 10px;
    line-height: 17px;
  }

  /* -------------------------
     IMPORTANT
     Override desktop nowrap
     ------------------------- */

  .sim-header * {
    white-space: normal;
  }

  .sim-nav,
  .sim-nav a,
  .sim-right,
  .navbar-right,
  .period-btn {
    white-space: nowrap;
  }

  /* -------------------------
     TOOLTIP
     ------------------------- */

  .sim-logo-tooltip-text,
  .sparkle-tooltip-text {
    display: none;
  }
}


/* =========================================================
   VERY SMALL PHONES
   320px - 480px
   ========================================================= */

@media (max-width: 480px) {

  .sim-container {
    padding: 8px 10px;
    gap: 6px;
  }

  .sim-left {
    gap: 7px;
  }

  .logo-img {
    height: 27px;
    max-width: 95px;
  }

  .sim-nav {
    gap: 2px;
  }

  .sim-nav a {
    padding: 6px 7px;
    font-size: 11px;
  }

  .sim-nav a.active {
    padding: 6px 7px;
  }

  .sim-right {
    gap: 5px;
  }

  .period-btn {
    padding: 4px 6px;
    font-size: 10px;
  }

  .sparkle-icon {
    width: 25px;
    height: 25px;
  }

  .profile-info h2 {
    font-size: 21px;
  }
}


/* =========================================================
   EXTRA SMALL PHONES
   ========================================================= */

@media (max-width: 360px) {

  .sim-container {
    padding-left: 8px;
    padding-right: 8px;
  }

  .logo-img {
    max-width: 80px;
  }

  .sim-nav a {
    padding: 5px 6px;
    font-size: 10px;
  }

  .period-btn {
    display: none;
  }

  .sparkle-icon {
    width: 23px;
    height: 23px;
  }
}

sp_header_footer.script:
(function() {

    data.user = {
        sys_id: gs.getUserID(),
        name: gs.getUserDisplayName(),
        logged_in: gs.getUserID() ? true : false
    };

    data.avatarProfile = {
        userID: data.user.sys_id,
        name: data.user.name

    };

    data.isIncentNowGroupAdmin = gs.hasRole('x_ctans_incentnow.business_group_admin') || gs.hasRole('x_ctans_incentnow.admin');
    data.isIncentNowUser = gs.hasRole('x_ctans_incentnow.user');

    var allowedReportRoles = [
        'x_ctans_incentnow.business_group_admin',
        'x_ctans_incentnow.admin',

        'x_ctans_incentnow.business_group_executive',
        'x_ctans_incentnow.manager',
        'x_ctans_incentnow.org_executive'
    ];

    data.canViewReports = false;

    for (var i = 0; i < allowedReportRoles.length; i++) {

        if (gs.hasRole(allowedReportRoles[i])) {
            //gs.addInfoMessage(allowedReportRoles[i]);
            data.canViewReports = true;
            break;
        }

    }


    data.initials = gs.getUser().getFirstName().charAt(0) + gs.getUser().getLastName().charAt(0);

    data.logoutUrl = "/logout.do";

    data.pageId = $sp.getParameter('id') || '';

    var approvalGR = new GlideAggregate('sysapproval_approver');
    approvalGR.addQuery('approver', gs.getUserID());
    approvalGR.addQuery('state', 'requested'); // pending approvals
    approvalGR.addAggregate('COUNT');
    approvalGR.query();

    data.approvalCount = 0;

    if (approvalGR.next())
        data.approvalCount = parseInt(approvalGR.getAggregate('COUNT'), 10);

})();
